    "questionBn": "একটি নল দিয়ে একটি চৌবাচ্চা ১২ মিনিটে পূর্ণ হয় এবং অপর নল দিয়ে ১৮ মিনিটে খালি হয়। দুটি নল একসাথে খুললে চৌবাচ্চাটি কত মিনিটে পূর্ণ হবে?",
